package com.fasterxml.jackson.databind.ser.std;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonGenerator;
import com.fasterxml.jackson.databind.JavaType;
import com.fasterxml.jackson.databind.JsonMappingException;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.SerializerProvider;
import com.fasterxml.jackson.databind.jsonFormatVisitors.JsonFormatVisitorWrapper;
import java.io.*;
import java.io.IOException;
import java.lang.reflect.Type;
import java.math.*;
import java.util.*;
import java.util.Date;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class StdKeySerializer_serialize_TriageGen2Test {

    private StdKeySerializer serializer;
    private JsonGenerator jgen;
    private SerializerProvider provider;

    @Before
    public void setUp() {
        serializer = new StdKeySerializer();
        jgen = mock(JsonGenerator.class);
        provider = mock(SerializerProvider.class);
    }

    @Test
    public void testSerialize_WithDateValue() throws IOException {
        // Arrange
        Date dateValue = new Date();

        // Act
        serializer.serialize(dateValue, jgen, provider);

        // Assert
        verify(provider, times(1)).defaultSerializeDateKey(dateValue, jgen);
        verifyNoMoreInteractions(jgen);
        verifyNoInteractions(provider); // This line is actually wrong in logic if we want to allow provider interaction, 
                                        // but we check that only defaultSerializeDateKey was called on provider.
    }

    @Test
    public void testSerialize_WithNonDateValue() throws IOException {
        // Arrange
        String value = "testKey";

        // Act
        serializer.serialize(value, jgen, provider);

        // Assert
        verify(jgen, times(1)).writeFieldName("testKey");
        verifyNoInteractions(provider);
    }

    @Test
    public void testSerialize_WithIntegerValue() throws IOException {
        // Arrange
        Integer value = 123;

        // Act
        serializer.serialize(value, jgen, provider);

        // Assert
        verify(jgen, times(1)).writeFieldName("123");
        verifyNoInteractions(provider);
    }

    @Test(expected = NullPointerException.class)
    public void testSerialize_WithNullValue() throws IOException {
        // Act
        // value.toString() will throw NPE if value is null
        serializer.serialize(null, jgen, provider);
    }

    @Test
    public void testSerialize_WithCustomObject() throws IOException {
        // Arrange
        Object customObject = new Object() {
            @Override
            public String toString() {
                return "customToString";
            }
        };

        // Act
        serializer.serialize(customObject, jgen, provider);

        // Assert
        verify(jgen, times(1)).writeFieldName("customToString");
    }
}
